  void eval(bool update_registers, bool verbose, bool done_reset) {
    this->update_registers = update_registers;
    this->verbose = verbose;
    this->done_reset = done_reset;

    thread_1_eval_token.store(true);

    eval_tp_0(update_registers, verbose, done_reset);

    while (thread_1_eval_token.load() == true) {
      _mm_pause();
    };

    thread_1_sync_token.store(true);

    sync_tp_0(update_registers);
    while (thread_1_sync_token.load() == true) {
      _mm_pause();
    };
  }
